function mean(xs) {
  if (xs.length === 0)
    return Number.NaN;
  let sum = 0;
  for (const x of xs)
    sum += x;
  return sum / xs.length;
}
function stdDev(xs) {
  if (xs.length === 0)
    return Number.NaN;
  const m = mean(xs);
  let variance = 0;
  for (const x of xs)
    variance += (x - m) * (x - m);
  return Math.sqrt(variance / xs.length);
}
function round(x, places) {
  if (Number.isNaN(x))
    return Number.NaN;
  let sign = 1;
  let v = x;
  if (v < 0) {
    sign = -1;
    v = -v;
  }
  const precision = 10 ** places;
  const digit = v * precision;
  const decimal = digit - Math.trunc(digit);
  const rounded = decimal >= 0.5 ? Math.ceil(digit) : Math.floor(digit);
  return rounded / precision * sign;
}
